// Form do Caio -> 1 linha de Baserow por peca. Status inicial = Fila (rascunho cru);
// o /agenda (modo lote) enriquece depois com foto + traducao + legenda.
//
// REGRA DURA - NAO usar $('nome-do-no') aqui. Ja quebrou 2x (15/07 e 16/07):
// ao importar por cima de um canvas existente o n8n renomeia os nos (Config -> Config1)
// e carimba o '1' ate em referencia de no que nao foi renomeado -> ExpressionError
// 'Referenced node doesn't exist', e o webhook devolve 200 VAZIO (falha silenciosa).
// Por isso o node Config esta com includeOtherFields=true: o body do webhook chega
// aqui dentro do $input, junto com os tokens. Zero dependencia de nome.
//
// NAO usar barra invertida em regex: some ao colar o codigo na mao no n8n.
const inp = $input.first().json;
const payload = inp.body || {};

if (!inp.form_secret || String(payload.secret || '').trim() !== String(inp.form_secret).trim()) {
  throw new Error('unauthorized: secret invalido');
}
const items = Array.isArray(payload.items) ? payload.items : [];
if (items.length === 0) throw new Error('sem itens');
if (items.length > 20) throw new Error('acima do teto de 20 por envio');

// Valor do Caio (R$) -> numero. Aceita 'R$ 750,00', '750,00', '1.250,50', '750'.
// Esse R$ JA E FECHADO: inclui frete do Japao + impostos (modelo de venda da NSC).
function parseBRL(s) {
  if (!s) return null;
  const raw = String(s);
  // Freio: se veio em iene, NAO adivinhar. '¥ 2.500' viraria 2.5 (R$ 2,50) e iria pro grupo errado.
  if (raw.indexOf('¥') > -1 || raw.indexOf('円') > -1 || raw.toUpperCase().indexOf('JPY') > -1) return null;
  let t = raw.replace(/[^0-9.,]/g, '').trim();
  if (!t) return null;
  if (t.indexOf(',') > -1) { t = t.split('.').join('').replace(',', '.'); }  // BR: ponto=milhar, virgula=decimal
  const n = parseFloat(t);
  return (isNaN(n) || n <= 0) ? null : n;
}

const out = [];
for (const it of items) {
  const url = (it && it.url ? String(it.url) : '').trim();
  const title = (it && it.title ? String(it.title) : '').trim();
  const note = (it && it.note ? String(it.note) : '').trim();
  const m = url.match(/m[0-9]+/i);   // so digitos, sem barra invertida
  if (!m) continue;
  const id = m[0].toLowerCase();
  const row = {
    mercari_id: id,
    source_url: url,
    title_pt: title || id,          // titulo do Caio (id como fallback); /agenda refina
    tags: note,                     // so a nota; o valor tem campo proprio
    status: 'Fila'
  };
  const brl = parseBRL(it && it.price);
  if (brl !== null) row.price_brl = brl;   // omite quando o Caio nao preencheu
  // config viaja junto: o HTTP node le tudo de $json, sem $('Config')
  out.push({ json: { row, baserow_url: inp.baserow_url, table_id: inp.table_id, baserow_token: inp.baserow_token } });
}
if (out.length === 0) throw new Error('nenhuma URL de Mercari valida');
return out;
